from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(token: str = Form(), file: bytes = File()):
    return {"token": token, "file": file}

client = TestClient(app)

def test_form_before_file():
    # Sending a form field and a file
    # If the bug exists, this should return 422 because 'file' is declared after 'token'
    response = client.post(
        "/test",
        data={"token": "secret"},
        files={"file": b"hello world"}
    )
    assert response.status_code == 200, f"Expected 200, got {response.status_code}: {response.text}"

def test_file_before_form():
    # This should work even with the bug
    @app.post("/test_reversed")
    async def test_reversed(file: bytes = File(), token: str = Form()):
        return {"token": token, "file": file}

    response = client.post(
        "/test_reversed",
        data={"token": "secret"},
        files={"file": b"hello world"}
    )
    assert response.status_code == 200, f"Expected 200, got {response.status_code}: {response.text}"

if __name__ == "__main__":
    try:
        test_form_before_file()
        print("test_form_before_file passed")
    except Exception as e:
        print(f"test_form_before_file failed: {e}")

    try:
        test_file_before_form()
        print("test_file_before_form passed")
    except Exception as e:
        print(f"test_file_before_form failed: {e}")

